// Demo tenant for judges / walkthroughs — local test credentials only.
export const demoTenant = {
  id: "seed-tenant-demo",
  email: "demo.tenant@leasematchuae.test",
  password: "LeaseMatch-tenant-2026",
  fullName: "Sara Demo",
};

export function seedSampleData(db: DatabaseSync) {
  if (process.env.LEASEMATCH_DISABLE_SEED === "1") return;

  const SEED_VERSION = "3-dubai-first";
  db.exec(`CREATE TABLE IF NOT EXISTS seed_meta (key TEXT PRIMARY KEY, value TEXT NOT NULL)`);
  const current = db.prepare(`SELECT value FROM seed_meta WHERE key = 'version'`).get() as
    | { value: string }
    | undefined;
  if (current?.value === SEED_VERSION) return;

  const hash = bcrypt.hashSync(SAMPLE_PROVIDER_PASSWORD, 10);
  const insertProfile = db.prepare(
    `INSERT OR IGNORE INTO profiles (id, email, password_hash, role, full_name, company_name)
     VALUES (?, ?, ?, ?, ?, ?)`
  );
  for (const p of sampleProviders) {
    insertProfile.run(p.id, p.email, hash, p.role, p.fullName, p.companyName);
  }
  db.prepare(
    `INSERT OR IGNORE INTO profiles (id, email, password_hash, role, full_name) VALUES (?, ?, ?, 'tenant', ?)`
  ).run(demoTenant.id, demoTenant.email, bcrypt.hashSync(demoTenant.password, 10), demoTenant.fullName);
  db.prepare(
    `INSERT INTO tenant_preferences (profile_id, property_types, locations, budget, furnished, notes)
     VALUES (?, ?, ?, ?, NULL, ?)
     ON CONFLICT (profile_id) DO UPDATE SET property_types = excluded.property_types,
       locations = excluded.locations, budget = excluded.budget, notes = excluded.notes`
  ).run(
    demoTenant.id,
    JSON.stringify(["Apartment", "Studio"]),
    JSON.stringify(["Dubai Marina", "Jumeirah Lake Towers"]),
    130000,
    "Relocating to Dubai for a new job in Dubai Internet City; would like to be near the metro around Dubai Marina or JLT."
  );

  // Upsert so content changes to the sample set reach existing databases;
  // status is left alone so a sample unit that's been leased stays leased.
  const insertProperty = db.prepare(
    `INSERT INTO properties
      (id, provider_id, title, property_type, location, price, beds, baths, sqft, furnished,
       description, amenities, photos, status, created_at)
     VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, 'live', datetime('now', ?))
     ON CONFLICT (id) DO UPDATE SET
       title = excluded.title, property_type = excluded.property_type, location = excluded.location,
       price = excluded.price, beds = excluded.beds, baths = excluded.baths, sqft = excluded.sqft,
       furnished = excluded.furnished, description = excluded.description,
       amenities = excluded.amenities, photos = excluded.photos`
  );
  for (const p of sampleProperties) {
    insertProperty.run(
      p.id,
      p.providerId,
      p.title,
      p.propertyType,
      p.location,
      p.price,
      p.beds,
      p.baths,
      p.sqft,
      p.furnished,
      p.description,
      JSON.stringify(p.amenities),
      JSON.stringify([`/properties/${p.photo}-a.svg`, `/properties/${p.photo}-b.svg`]),
      `-${p.daysListed} days`
    );
  }

  db.prepare(
    `INSERT INTO seed_meta (key, value) VALUES ('version', ?)
     ON CONFLICT (key) DO UPDATE SET value = excluded.value`
  ).run(SEED_VERSION);
}
